import unittest
from calc import evaluate, ExpressionError


class TestCalc(unittest.TestCase):
    def test_single_integer(self):
        self.assertEqual(evaluate("123"), 123.0)

    def test_addition_multiplication(self):
        self.assertEqual(evaluate("2+3*4"), 14.0)

    def test_parentheses_and_negation(self):
        self.assertEqual(evaluate("(1+2.5)*-3"), -10.5)

    def test_division(self):
        self.assertEqual(evaluate("10/4"), 2.5)

    def test_unary_minus(self):
        self.assertEqual(evaluate("-5+10"), 5.0)

    def test_division_by_zero(self):
        with self.assertRaisesRegex(ExpressionError, "Division by zero"):
            evaluate("10/0")

    def test_empty_expression(self):
        with self.assertRaisesRegex(ExpressionError, "Empty expression"):
            evaluate("")

    def test_trailing_characters(self):
        with self.assertRaisesRegex(ExpressionError, "Trailing characters in expression"):
            evaluate("2+3abc")

    def test_unbalanced_parentheses(self):
        with self.assertRaisesRegex(ExpressionError, "Unbalanced parentheses"):
            evaluate("(1+2")


if __name__ == '__main__':
    unittest.main()
